package vn.terrawatch.core.dto;

import jakarta.validation.constraints.DecimalMax;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.PositiveOrZero;
import jakarta.validation.constraints.Size;

import java.time.OffsetDateTime;
import java.util.UUID;

/**
 * A field report from the mobile app. The reporter is the signed-in user (never taken from the body).
 * clientReportId is generated by the app so that retries after a lost connection do not create duplicates.
 * observedAt/observedUntil say when the event was seen; the server records its own receive time separately.
 */
public record CommunityReportRequest(
    @NotNull UUID clientReportId,
    @NotNull @DecimalMin("-180") @DecimalMax("180") Double longitude,
    @NotNull @DecimalMin("-90") @DecimalMax("90") Double latitude,
    @PositiveOrZero Double accuracyM,
    @Size(max = 2000) String description,
    UUID photoId,
    @NotNull OffsetDateTime observedAt,
    OffsetDateTime observedUntil
) {}
